392	    /** Add a claim for a person; a claim without a date is dated the sheet's today. One dated in a closed period
393	     * is refused, and so is a correction that does not name a settled claim of the same person. */
394	    @Transactional
395	    public Claim add(String user, String sheetId, Long personId, BigDecimal amount, LocalDate date, String note,
396	            String corrects) {
397	        LocalDate today = sheets.today(sheetId);
398	        Person person = requirePerson(sheetId, personId);
399	        requireNotRetired(person, date != null ? date : today);
400	        requireOpenPeriod(sheetId, date != null ? date : today);
401	        String corrected = correctedBy(sheetId, personId, amount, corrects);
402	        Snapshot before = rollup.snapshot(sheetId);
403	        LocalDate dated = date != null ? date : today;
404	        // The due-by is fixed now, from the terms in force for the grade the person has on the claim's date.
405	        LocalDate dueBy = dated.plusDays(settings.termsFor(sheetId, person.gradeOn(dated)));
406	        Claim fresh = new Claim(sheetId, personId, amount, dated, dueBy, noteOf(note));
407	        fresh.setCorrects(corrected);
408	        Claim claim = claims.saveAndFlush(fresh);
409	        audit.recordOnCommit(entry("CLAIM_ADDED", user, person, claim));
410	        rollup.recordChanges(user, sheetId, before);
411	        return claim;
412	    }
413	
414	    /** Edit a claim; only a draft can be edited (an open claim is voided and added again instead), and one dated
415	     * in a closed period, or that would be, is refused, as is a correction that does not name a settled claim of
416	     * the same person. */
417	    @Transactional
418	    public Claim update(String user, String sheetId, Long id, BigDecimal amount, LocalDate date, String note,
419	            String corrects) {
420	        LocalDate today = sheets.today(sheetId);
421	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
422	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
423	        if (claim.getStatus() != ClaimStatus.DRAFT) {
424	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft claim can be edited.");
425	        }
426	        requireOpenPeriod(sheetId, claim.getDate());
427	        requireOpenPeriod(sheetId, date != null ? date : today);
428	        requireNotRetired(requirePerson(sheetId, claim.getPersonId()), date != null ? date : today);
429	        String corrected = correctedBy(sheetId, claim.getPersonId(), amount, corrects);
430	        Snapshot before = rollup.snapshot(sheetId);
431	        claim.setAmount(amount);
432	        claim.setCorrects(corrected);
433	        claim.setDate(date != null ? date : today);
434	        claim.setNote(noteOf(note));
435	        claims.flush();
436	        audit.recordOnCommit(entry("CLAIM_EDITED", user, requirePerson(sheetId, claim.getPersonId()), claim));
437	        rollup.recordChanges(user, sheetId, before);
438	        return claim;
439	    }
440	
441	    /** Move a claim to another status; a change its status does not allow, or of a claim dated in a closed
442	     * period, is refused. A settle by a clerk of a claim whose due is above the clerk limit sends it PENDING a
443	     * steward instead. */
444	    @Transactional
445	    public Claim changeStatus(String user, String sheetId, Long id, ClaimStatus next) {
446	        sheets.today(sheetId); // the sheet must exist
447	        // Locking the sheet before taking the number opens claims one at a time; a refused open rolls back
448	        // and gives the number back.
449	        if (next == ClaimStatus.OPEN) {
450	            sheets.lock(sheetId);
451	        }
452	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
453	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
454	        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : null;
455	        requireOpenPeriod(sheetId, claim.getDate());
456	        if (!claim.getStatus().canBecome(next)) {
457	            throw new ResponseStatusException(HttpStatus.CONFLICT,
458	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
459	        }
460	        // Four eyes: whoever opened a claim cannot also settle it.
461	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
462	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it.");
463	        }
464	        Person person = requirePerson(sheetId, claim.getPersonId());
465	        BigDecimal due = rollup.dueOf(claim, person);
466	        // A clerk settles only a claim whose due is within the sheet's clerk limit; above it, a steward must
467	        // approve it.
468	        if (next == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, due)) {
469	            next = ClaimStatus.PENDING;
470	        }
471	        Snapshot before = rollup.snapshot(sheetId);
472	        claim.setStatus(next);
473	        if (next == ClaimStatus.OPEN) {
474	            claim.setNumber(number);
475	            claim.setOpenedBy(user);
476	        }
477	        // A voided claim's line carries the number it had.
478	        String entry = entry(EVENTS.get(next), user, person, claim);
479	        if (next == ClaimStatus.SETTLED) {
480	            // Settling fixes the due at the figure the claim has: the one its last statement bound it to, else
481	            // the rate its grade has on its date; with no figure it stays live. The late charge it has (taken
482	            // while it is still OPEN) is frozen in.
483	            entry += settle(claim, due);
484	        }
485	        claims.flush();
486	        audit.recordOnCommit(entry);
487	        rollup.recordChanges(user, sheetId, before);
488	        return claim;
489	    }
490	
491	    /** A steward approves a PENDING claim: it is SETTLED at the due it has now, its live figure with any late
492	     * charge, frozen. The user who opened it cannot approve it. */
493	    @Transactional
494	    public Claim approve(String user, String sheetId, Long id) {
495	        Claim claim = requirePending(user, sheetId, id);
496	        if (user.equals(claim.getOpenedBy())) {
497	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it.");
498	        }
499	        Person person = requirePerson(sheetId, claim.getPersonId());
500	        Snapshot before = rollup.snapshot(sheetId);
501	        BigDecimal due = rollup.dueOf(claim, person);
502	        claim.setStatus(ClaimStatus.SETTLED);
503	        String entry = entry("CLAIM_APPROVED", user, person, claim) + settle(claim, due);
504	        claims.flush();
505	        audit.recordOnCommit(entry);
506	        rollup.recordChanges(user, sheetId, before);
507	        return claim;
508	    }
509	
510	    /** A steward rejects a PENDING claim with a reason: it is OPEN again, bound again by its person's last
511	     * statement if that statement included it. */
512	    @Transactional
513	    public Claim reject(String user, String sheetId, Long id, String reason) {
514	        Claim claim = requirePending(user, sheetId, id);
515	        Person person = requirePerson(sheetId, claim.getPersonId());
516	        Snapshot before = rollup.snapshot(sheetId);
517	        claim.setStatus(ClaimStatus.OPEN);
518	        claims.flush();
519	        audit.recordOnCommit(entry("CLAIM_REJECTED", user, person, claim) + " reason=" + reason.trim());
520	        rollup.recordChanges(user, sheetId, before);
521	        return claim;
522	    }
523	
524	    /** A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and
525	     * date but loses any figure a statement bound it to: it is live again until its new person's next statement.
526	     * One dated in a closed period, a correction (which names a settled claim of its own person), or one dated
527	     * after its new person is retired, is refused. */
528	    @Transactional
529	    public Claim reassign(String user, String sheetId, Long id, Long toPersonId) {
530	        sheets.today(sheetId); // the sheet must exist
531	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
532	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
533	        settings.requireSteward(sheetId, user);
534	        requireOpenPeriod(sheetId, claim.getDate());
535	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
536	            throw new ResponseStatusException(HttpStatus.CONFLICT,
537	                    "A " + claim.getStatus() + " claim cannot be moved.");
538	        }
539	        if (claim.isCorrection()) {
540	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A correction cannot be moved.");
541	        }
542	        Person from = requirePerson(sheetId, claim.getPersonId());
543	        Person to = requirePerson(sheetId, toPersonId);
544	        if (from.getId().equals(to.getId())) {
545	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim is already that person's.");
546	        }
547	        if (to.retiredOn(claim.getDate())) {
548	            throw new ResponseStatusException(HttpStatus.GONE,
549	                    to.getName() + " is retired from " + to.getRetiredFrom() + ".");
550	        }
551	        Snapshot before = rollup.snapshot(sheetId);
552	        claim.setPersonId(to.getId());
553	        claim.unbind();
554	        claims.flush();
555	        audit.recordOnCommit(entry("CLAIM_REASSIGNED", user, to, claim) + " from=" + from.getName() + " to="
556	                + to.getName());
557	        rollup.recordChanges(user, sheetId, before);
558	        return claim;
559	    }
560	
561	    /** The PENDING claim a steward acts on; refused when it is not on the sheet, not PENDING, dated in a closed
562	     * period, or the user is not a steward. */
563	    private Claim requirePending(String user, String sheetId, Long id) {
564	        sheets.today(sheetId); // the sheet must exist
565	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
566	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
567	        requireOpenPeriod(sheetId, claim.getDate());
568	        if (claim.getStatus() != ClaimStatus.PENDING) {
569	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a PENDING claim can be approved or rejected.");
570	        }
571	        settings.requireSteward(sheetId, user);
572	        return claim;
573	    }
574	
575	    /** Fix a claim's due at the given figure (none stays live), giving the end of its audit line. */
576	    private static String settle(Claim claim, BigDecimal due) {
577	        claim.setSettledDue(due);
578	        return " due=" + (due != null ? due.toPlainString() : "n/a");
579	    }
580	
581	    /** What opening claims together did: how many were opened and refused, and the opened claims. */
582	    public record OpenedAll(int opened, int refused, List<Claim> claims) {}
583	
584	    /** Open the given claims of the sheet one at a time, in list order: people in the order they were added,
585	     * each one's claims newest first. Each is opened, and numbered, as {@link #changeStatus} would open it on its
586	     * own; one that cannot be opened (or is not on the sheet) is refused and left as it is. */
587	    public OpenedAll openAll(String user, String sheetId, List<Long> ids) {
588	        Set<Long> wanted = new HashSet<>(ids);
589	        List<Claim> chosen = transaction.execute(status -> {
590	            sheets.today(sheetId); // the sheet must exist
591	            Map<Long, Integer> personOrder = new HashMap<>();
592	            for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
593	                personOrder.put(person.getId(), personOrder.size());
594	            }
595	            return claims.findBySheetIdOrderByIdDesc(sheetId).stream()
596	                    .filter(c -> wanted.contains(c.getId()))
597	                    .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
598	                    .toList();
599	        });
600	        List<Claim> opened = new ArrayList<>();
601	        for (Claim claim : chosen) {
602	            try {
603	                opened.add(transaction.execute(status -> changeStatus(user, sheetId, claim.getId(), ClaimStatus.OPEN)));
604	            } catch (ResponseStatusException refused) {
605	                // Left as it is: its transaction rolled back, writing nothing.
606	            }
607	        }
608	        return new OpenedAll(opened.size(), wanted.size() - opened.size(), opened);
609	    }
610	
611	    /** The sequence a claim in no period is numbered in, with period numbering. */
612	    private static final String NO_PERIOD = "X";
613	
614	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
615	            ClaimStatus.OPEN, "CLAIM_OPENED",
616	            ClaimStatus.PENDING, "CLAIM_PENDING",
617	            ClaimStatus.SETTLED, "CLAIM_SETTLED",
618	            ClaimStatus.VOID, "CLAIM_VOIDED");
619	
620	    /** The figure a claim has now: what it was settled at, else what its person's last statement bound it to,
621	     * else what is due at the rate of the grade its person has on its date; none when that is n/a. */
622	    public BigDecimal figureOf(Claim claim, Person person) {
623	        return rollup.figureOf(claim, person);
624	    }
625	
626	    /** The number a claim opened now takes: the sheet's next number or, with period numbering in force, the next
627	     * in its period's own sequence, <period name>-<n>, or X-<n> for a claim in no period. */
628	    private String nextNumber(String sheetId, Claim claim) {
629	        if (!sheets.numbersByPeriod(sheetId)) {
630	            return String.valueOf(sheets.nextClaimNumber(sheetId));
631	        }
632	        String prefix = periods.periodOf(sheetId, claim.getDate()).map(Period::getName).orElse(NO_PERIOD) + "-";
633	        int last = 0;
634	        for (Claim other : claims.findBySheetIdOrderByIdDesc(sheetId)) {
635	            String number = other.getNumber();
636	            if (number != null && number.startsWith(prefix)) {
637	                String rest = number.substring(prefix.length());
638	                if (rest.matches("\\d{1,9}")) {
639	                    last = Math.max(last, Integer.parseInt(rest));
640	                }
641	            }
642	        }
643	        return prefix + (last + 1);
644	    }
645	
646	    /** The number a claim of this amount corrects: none unless the amount is negative, when it must name a
647	     * SETTLED claim of the same person, or the claim is refused. */
648	    private String correctedBy(String sheetId, Long personId, BigDecimal amount, String corrects) {
649	        if (amount.signum() >= 0) {
650	            return null;
651	        }
652	        String named = corrects == null ? null : corrects.trim();
653	        boolean settled = named != null && claims.findBySheetIdAndPersonId(sheetId, personId).stream()
654	                .anyMatch(c -> named.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
655	        if (!settled) {
656	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
657	                    "A correction must name a settled claim of the same person.");
658	        }
659	        return named;
660	    }
661	
662	    /** Refuse a change to a claim dated in a closed period. Locks the sheet first, so a period cannot close
663	     * while the change is made. */
664	    private void requireOpenPeriod(String sheetId, LocalDate date) {
665	        sheets.lock(sheetId);
666	        periods.requireOpen(sheetId, date);
667	    }
668	
669	    /** Refuse a claim dated after its person's retirement. */
670	    private static void requireNotRetired(Person person, LocalDate date) {
671	        if (person.retiredOn(date)) {
672	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
673	                    person.getName() + " is retired from " + person.getRetiredFrom() + ".");
674	        }
675	    }
676	
677	    private Person requirePerson(String sheetId, Long personId) {
678	        return people.findByIdAndSheetId(personId, sheetId)
679	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
680	    }
681	
682	    /** The amount is written as the screen shows it, with two decimals; the date as yyyy-mm-dd; a
683	     * claim with a number ends with it. */
684	    private static String entry(String event, String user, Person person, Claim claim) {
685	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
686	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
687	                + (claim.getNumber() != null ? " number=" + claim.getNumber() : "");
688	    }
689	
690	    private static String noteOf(String note) {
691	        return note == null ? "" : note.trim();
692	    }
693	}
694	package net.officefloor.hq.app.claim;
695	
696	/** A claim's status. Only OPEN, PENDING and SETTLED claims count toward what is claimed and due. A PENDING claim
697	 * was settled by a clerk above the clerk limit and waits for a steward to approve it (SETTLED) or reject it
698	 * (OPEN again). */
699	public enum ClaimStatus {
700	    DRAFT, OPEN, PENDING, SETTLED, VOID;
701	
702	    /** Whether a claim in this status may be opened, settled (or sent PENDING) or voided to the given status. A
703	     * PENDING claim moves on only by a steward's approval or rejection, or by being voided. */
704	    public boolean canBecome(ClaimStatus next) {
705	        return switch (next) {
706	            case OPEN -> this == DRAFT;
707	            case PENDING, SETTLED -> this == OPEN;
708	            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
709	            case DRAFT -> false;
710	        };
711	    }
712	
713	    /** Whether a claim in this status is still open: OPEN, or PENDING a steward. Such a claim goes overdue, bears
714	     * the late charge, and a hold takes it out of the totals. */
715	    public boolean isOpen() {
716	        return this == OPEN || this == PENDING;
717	    }
718	}
